/// <summary>
/// PricingAttribute of table <c>SalesLine</c> field DlvTerm.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::SalesLine, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeSalesLineDlvTerm extends UPSPricingAttributeSalesLine implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(SalesLine, DlvTerm);
}

public Set getAllowedValues()
{
    var         ret = new Set(Types::String);
    SalesLine   salesLine;

    while select salesLine
        group by DlvTerm
    {
        if (! ret.in(salesLine.DlvTerm))
        {
            ret.add(salesLine.DlvTerm);
        }
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(SalesLine, DlvTerm));
    qbr.value(queryValue(_value));
}
